1. reverse_radix2_vector2_etalon
Эталонный вариант для сравнения на корректность.
Здесь
reverseNumber_radix2
вычисляется с помощью цикла.
int reverseNumber_radix2(int number, int bit_count)
{
	int answer = 0;

	for(int i = 0; i < bit_count; ++i)
	{
 answer <<= 1;
 answer |= number & 1;
 number >>= 1;
	}

	return answer;
}

void reverse_radix2_vector2_etalon(int bit_count_in, myComplex *data_in, myComplex2 *data_out)
{
	int bit_count_out = bit_count_in - 1;

//	int count_in = 1 << bit_count_in;
	int count_out = 1 << bit_count_out;

	for(int64_t i = 0; i < count_out; ++i)
	{
 int index = reverseNumber_radix2(i, bit_count_out);
 myComplex a = data_in[2*i + 0];
 myComplex b = data_in[2*i + 1];
 data_out[index] = (myComplex2){.real = {a.real, b.real}, .imag = {a.imag, b.imag}};
	}
}
