	__v2di *in = (__v2di*)data_in;
	__v2di *out = (__v2di*)data_out;

	#pragma ivdep
	#pragma unroll(1)
	#pragma prefetch
	for(int64_t i = 0; i < count_out; ++i)
	{
 int64_t index = __builtin_e2k_bitrevd(i) >> shift_out;
 __v2di mask = {0x0B0A090803020100, 0x0F0E0D0C07060504};
 out[index] = __builtin_e2k_qppermb(in[i], in[i], mask);
	}
}
