void reverse_radix2_vector2_x2(int bit_count_in, myComplex *data_in, myComplex2 *data_out)
{
	int bit_count_out = bit_count_in - 1;

//	int count_in = 1 << bit_count_in;
	int count_out = 1 << bit_count_out;
	int shift_out = 64 - bit_count_out;
	int64_t delta = (1LL << shift_out) / 16;

	__v2di *in = (__v2di*) data_in;
	__v2di *out_0 = (__v2di*)&data_out[0];
	__v2di *out_1 = (__v2di*)&data_out[count_out/2];

	#pragma ivdep
	#pragma unroll(1)
	#pragma prefetch
	for(int64_t i = 0, shifted_i = 0; i < count_out; i += 2, shifted_i += 2*delta)
	{
 int64_t offset = __builtin_e2k_bitrevd(shifted_i);
 __v2di mask = {0x0B0A090803020100, 0x0F0E0D0C07060504};
 *(__v2du*)((void*)out_0 + offset) = __builtin_e2k_qppermb(in[i + 0], in[i + 0], mask);
 *(__v2du*)((void*)out_1 + offset) = __builtin_e2k_qppermb(in[i + 1], in[i + 1], mask);
	}
}
