void reverse_radix2_vector4(int bit_count_in, myComplex *data_in, myComplex4 *data_out)
{
	int bit_count_out = bit_count_in - 2;

//	int count_in = 1 << bit_count_in;
	int count_out = 1 << bit_count_out;
	int shift_out = 64 - bit_count_out;
	int64_t delta = (1LL << shift_out) / 32;

	__v2di *in = (__v2di*)data_in;

	#pragma ivdep
	#pragma unroll(1)
	#pragma prefetch
	for(int64_t i = 0, shifted_i = 0; i < count_out; ++i, shifted_i += delta)
	{
 int64_t offset = __builtin_e2k_bitrevd(shifted_i);
 __v2di mask_real = {0x0B0A090803020100, 0x1B1A191813121110};
 __v2di mask_imag = {0x0F0E0D0C07060504, 0x1F1E1D1C17161514};
 *(__v2du*)((void*)data_out + offset + 0*16) = __builtin_e2k_qppermb(in[2*i+1], in[2*i+0], mask_real);
 *(__v2du*)((void*)data_out + offset + 1*16) = __builtin_e2k_qppermb(in[2*i+1], in[2*i+0], mask_imag);
	}
}
