void stage_radix2_vector2_etalon(int data_count, myComplex2 *data_in, myComplex2 *data_out, myComplex2 *coef)
{
	myComplex2 *x_in = &data_in[0];
	myComplex2 *y_in = &data_in[1];
	myComplex2 *c_in = coef;

	myComplex2 *out_add = &data_out[0];
	myComplex2 *out_sub = &data_out[data_count/2];

	#pragma ivdep
	#pragma unroll(1)
//	#pragma prefetch
	for(int64_t i = 0; i < data_count/2; ++i)
	{
 myComplex2 x = x_in[2*i];
 myComplex2 y = y_in[2*i];
 myComplex2 c = c_in[i];

 myComplex2 cy = complex2_mul(c, y);

 out_add[i] = complex2_add(x, cy);
 out_sub[i] = complex2_sub(x, cy);
	}
}
