void stage_radix2_vector2(int data_count, myComplex2 *data_in, myComplex2 *data_out, myComplex2 *coef)
{
	uint64_t *x_real_in = (uint64_t*)&data_in[0].real;
	uint64_t *x_imag_in = (uint64_t*)&data_in[0].imag;
	uint64_t *y_real_in = (uint64_t*)&data_in[1].real;
	uint64_t *y_imag_in = (uint64_t*)&data_in[1].imag;
	uint64_t *c_real_in = (uint64_t*)&coef[0].real;
	uint64_t *c_imag_in = (uint64_t*)&coef[0].imag;

	uint64_t *out_add_real = (uint64_t*)&data_out[0].real;
	uint64_t *out_add_imag = (uint64_t*)&data_out[0].imag;
	uint64_t *out_sub_real = (uint64_t*)&data_out[data_count/2].real;
	uint64_t *out_sub_imag = (uint64_t*)&data_out[data_count/2].imag;

	#pragma ivdep
	#pragma unroll(1)
	#pragma prefetch
	for(int64_t i = 0; i < data_count/2; ++i)
	{
 uint64_t x_real = x_real_in[4*i];
 uint64_t x_imag = x_imag_in[4*i];
 uint64_t y_real = y_real_in[4*i];
 uint64_t y_imag = y_imag_in[4*i];
 uint64_t c_real = c_real_in[2*i];
 uint64_t c_imag = c_imag_in[2*i];

 uint64_t cy_real = __builtin_e2k_pfsubs(__builtin_e2k_pfmuls(c_real, y_real), __builtin_e2k_pfmuls(c_imag, y_imag));
 uint64_t cy_imag = __builtin_e2k_pfadds(__builtin_e2k_pfmuls(c_real, y_imag), __builtin_e2k_pfmuls(c_imag, y_real));

 out_add_real[2*i] = __builtin_e2k_pfadds(x_real, cy_real);
 out_add_imag[2*i] = __builtin_e2k_pfadds(x_imag, cy_imag);
 out_sub_real[2*i] = __builtin_e2k_pfsubs(x_real, cy_real);
 out_sub_imag[2*i] = __builtin_e2k_pfsubs(x_imag, cy_imag);
	}
