{
	myComplex4 *x_in = &data_in[0];
	myComplex4 *y_in = &data_in[1];
	myComplex4 *z_in = &data_in[2];
	myComplex4 *w_in = &data_in[3];
	myComplex4 *c_in = coefC;
	myComplex4 *d_in = coefD;
	myComplex4 *e_in = coefE;

	myComplex4 *out_0 = &data_out[0*data_count/4];
	myComplex4 *out_1 = &data_out[1*data_count/4];
	myComplex4 *out_2 = &data_out[2*data_count/4];
	myComplex4 *out_3 = &data_out[3*data_count/4];

	#pragma ivdep
	#pragma unroll(1)
//	#pragma prefetch
	for(int64_t i = 0; i < data_count/4; ++i)
	{
 myComplex4 x = x_in[4*i];
